import socket,ssl,json,urllib.request,urllib.error,pathlib,time
names=["vivo-team.duckdns.org","vivoteam.dns.org","www.vivo-player.com"]
result={"tests":[],"browser":[]}
for host in names:
 rec={"host":host}
 try:
  addrs=socket.getaddrinfo(host,None,type=socket.SOCK_STREAM)
  rec["dns"]={"ok":True,"unique_ip_count":len(set(x[4][0] for x in addrs))}
 except Exception as e:
  rec["dns"]={"ok":False,"error":str(e)[:140]}
 if rec["dns"]["ok"]:
  for scheme in ("https","http"):
   req=urllib.request.Request(scheme+"://"+host+"/",method="HEAD",headers={"User-Agent":"Mozilla/5.0 FerrariAuthorizedInteropProbe/1.0"})
   try:
    with urllib.request.urlopen(req,timeout=5) as r:
     rec[scheme]={"status":r.status,"final_host":urllib.parse.urlsplit(r.url).hostname,"content_type":r.headers.get("Content-Type","")[:120]}
   except urllib.error.HTTPError as e:
    rec[scheme]={"status":e.code,"content_type":e.headers.get("Content-Type","")[:120]}
   except Exception as e:
    rec[scheme]={"error":str(e)[:180]}
 result["tests"].append(rec)
base=pathlib.Path("/srv/projects/skill-universal/.runtime/browsers")
if base.is_dir():
 for f in sorted(base.glob("chromium_headless_shell-*/chrome-headless-shell-linux64/chrome-headless-shell"))[:10]:
  result["browser"].append({"path":str(f),"is_file":f.is_file(),"is_executable":bool(f.stat().st_mode & 0o111) if f.is_file() else False})
print(json.dumps(result,ensure_ascii=False))
